  "headline": "Protamine sulfate is not on FDA's current shortage list; the earlier shortage posted 2021-04-20 is resolved",
  "headline_cites": ["D8"],
  "sentences": [
    {
      "text": "FDA's records show protamine sulfate is not on the current shortage list as of 2026-10-21, and the earlier shortage first posted on 2021-04-20 has been resolved.",
      "cites": ["D8"]
    },
    {
      "text": "The product label links our supply to Fresenius Kabi USA, LLC (FEI 1450022), a registered plant.",
      "cites": ["E11"]
    },
    {
      "text": "FDA inspected that plant on 2020-05-18 and classified it OAI, 337 days before the 2021-04-20 shortage posting.",
      "cites": ["D3"]
    },
    {
      "text": "A later inspection on 2022-06-30 was also classified OAI, 436 days after the posting.",
      "cites": ["D4"]
    },
    {
      "text": "The most recent inspection on 2023-08-24 was classified VAI.",
      "cites": ["E10"]
    },
    {
      "text": "Corvale East has 31.1 days on hand and Corvale General has 14.9 days on hand for the 10 mg/mL, 5 mL vial presentation.",
      "cites": ["D1", "D2"]
    }
  ]
}
